protected static function apply_axis_defaults( $rt, $in ) {
	if ( ! is_array( $rt['axis_policy'] ?? null ) || empty( $rt['rows'] ) ) { return array( $rt, false ); }
	foreach ( array_keys( $rt['axis_policy'] ) as $ax ) {
		$spec = $rt['axis_policy'][ $ax ];
		$kind = is_array( $spec ) ? ( $spec['kind'] ?? null ) : null;
		if ( $kind !== 'categorical' ) { continue; }
		if ( $ax === 'activity_level' ) { continue; }

		$joined = strtolower( (string) $ax ) . ' ';
		foreach ( $rt['rows'] as $r ) {
			$joined .= strtolower( (string) ( $r['conditions'][ $ax ] ?? '' ) ) . ' ' . strtolower( (string) ( $r['condition_raw'][ $ax ] ?? '' ) ) . ' ';
		}

		$pick = null;
		if ( preg_match( '/svorio_valdym|weight_goal/i', $ax ) || ( preg_match( '/palaik|maintain/u', $joined ) && preg_match( '/ma\x{017e}in|mazin|reduc|loss/u', $joined ) ) ) {
			$pick = '/palaik|maintain/u';
		} elseif ( preg_match( '/body_condition|kuno_bukle/i', $ax ) ) {
			$pick = '/(^|[^a-z])normal/u';
		} elseif ( preg_match( '/housing|laikym/i', $ax ) ) {
			$pick = '/(^|[^a-z])indoor/u';
		}

		if ( $pick ) {
			$keep = array();
			foreach ( $rt['rows'] as $r ) {
				$cv = strtolower( (string) ( $r['conditions'][ $ax ] ?? '' ) );
				if ( preg_match( $pick, $cv ) ) { unset( $r['conditions'][ $ax ] ); $keep[] = $r; }
			}
			if ( $keep ) { $rt['rows'] = $keep; unset( $rt['axis_policy'][ $ax ] ); }
			continue;
		}

		if ( preg_match( '/age_range|amziaus_tarpsnis/i', $ax ) ) {
			$am = ( isset( $in['age_months'] ) && $in['age_months'] !== null && $in['age_months'] !== '' ) ? (float) $in['age_months'] : null;
			if ( $am === null ) { return array( $rt, true ); }
			$keep = array(); $best = null; $bestd = null; $byraw = array();
			foreach ( $rt['rows'] as $r ) {
				// Repository normalizuotos eilutes gali netureti condition_raw — imam koda.
				$raw = (string) ( $r['condition_raw'][ $ax ] ?? $r['conditions'][ $ax ] ?? '' );
				$lo = null; $hi = null;
				if ( preg_match( '/(\d+(?:[.,]\d+)?)\s*[-\x{2013}\x{2014}]\s*(\d+(?:[.,]\d+)?)/u', $raw, $m ) ) {
					$lo = (float) str_replace( ',', '.', $m[1] ); $hi = (float) str_replace( ',', '.', $m[2] );
				} elseif ( preg_match( '/[>\x{2265}]\s*(\d+(?:[.,]\d+)?)/u', $raw, $m ) ) {
					$lo = (float) str_replace( ',', '.', $m[1] ); $hi = 240.0;
				} elseif ( preg_match( '/(\d+(?:[.,]\d+)?)/u', $raw, $m ) ) {
					$lo = (float) str_replace( ',', '.', $m[1] ); $hi = $lo;
				}
				if ( $lo === null ) { continue; }
				if ( preg_match( '/savait|week/u', mb_strtolower( $raw ) ) ) { $lo = $lo / 4.345; $hi = $hi / 4.345; }
				$rr = $r; unset( $rr['conditions'][ $ax ] );
				if ( $am >= $lo && $am <= $hi ) { $keep[] = $rr; }
				$byraw[ $raw ][] = $rr;
				$d = min( abs( $am - $lo ), abs( $am - $hi ) );
				if ( $bestd === null || $d < $bestd ) { $bestd = $d; $best = $raw; }
			}
			// Gamintojas praleidzia menesi -> artimiausias stulpelis (stulpelio pasirinkimas, ne spejimas).
			if ( ! $keep && $best !== null && isset( $byraw[ $best ] ) ) { $keep = $byraw[ $best ]; }
			if ( $keep ) {
				$rt['rows'] = $keep; unset( $rt['axis_policy'][ $ax ] );
			}
		}
